    10→use super::errors::VerifierError;
    11→use crate::{
    12→    fk20::cosets::{coset_gens, reverse_bit_order},
    13→    verification_key::VerificationKey,
    14→};
    15→
    16→/// CosetIndex is a reference to a coset.
    17→///
    18→/// Note: We are able to use CosetIndex instead of the coset because
    19→/// the prover and verifier both know what the cosets are that
    20→/// we will be making and verifying opening proofs for.
    21→pub type CosetIndex = u64;
    22→
    23→/// CommitmentIndex is a reference to a commitment.
    24→///
    25→/// In order to make verification cheaper, the verifier will
    26→/// deduplicate the list of commitments that are needed in order to verify opening proofs.
    27→/// They will then refer to a commitment via its position in an array of deduplicated commitments
    28→/// with the CommitmentIndex.
    29→pub type CommitmentIndex = u64;
    30→
    31→/// FK20Verifier initializes all of the components needed to verify KZG multi point
    32→/// proofs that were created using the FK20Prover.
    33→///
    34→/// Note: The proofs can be created naively not using the FK20 strategy (see naive.rs)
    35→/// however, we put FK20 in the name since:
    36→///  - From the callers perspective, this distinction is not important
    37→///  - We only use FK20 to create proofs
    38→#[derive(Debug)]
    39→pub struct FK20Verifier {
    40→    pub verification_key: VerificationKey,
    41→    pub coset_gens_bit_reversed: Vec<Scalar>,
    42→    coset_domain: Domain,
    43→    // Pre-computations for the verification algorithm
    44→    //
    45→    // [tau^n]_2
    46→    tau_pow_n: G2Prepared,
    47→    // [-1]_2
    48→    neg_g2_gen: G2Prepared,
    49→    // Bit reversed vector of the coset generators raised
    50→    // to the power of `n`, needed to verify a multi opening proof.
    51→    pub bit_reversed_coset_gens_pow_n: Vec<Scalar>,
    52→    // Bit reversed vector of the coset generators that
    53→    // we will use to compute an inverse coset IFFT.
    54→    bit_reversed_coset_fft_gens: Vec<CosetFFT>,
    55→}
    56→
    57→impl FK20Verifier {
    58→    pub fn new(
    59→        verification_key: VerificationKey,
    60→        num_points_to_open: usize,
    61→        num_cosets: usize,
    62→    ) -> Self {
    63→        const BIT_REVERSED: bool = true;
    64→
    65→        assert!(
    66→            verification_key.coset_size.is_power_of_two(),
    67→            "coset size must be a power of two"
    68→        );
    69→        assert!(
    70→            num_cosets * verification_key.coset_size == num_points_to_open,
    71→            "Expected {} * {} == {}",
    72→            num_cosets,
    73→            verification_key.coset_size,
    74→            num_points_to_open
    75→        );
    76→
    77→        let coset_gens = coset_gens(num_points_to_open, num_cosets, BIT_REVERSED);
    78→
    79→        let coset_size = num_points_to_open / num_cosets;
    80→        assert!(
    81→            verification_key.g2s.len() >= coset_size,
    82→            "need as many g2 points as coset size"
    83→        );
    84→        let coset_domain = Domain::new(verification_key.coset_size);
    85→
    86→        let n = verification_key.coset_size;
    87→        // [tau^n]_2
    88→        let tau_pow_n = G2Prepared::from(verification_key.g2s[n]);
    89→        // [-1]_2
    90→        let neg_g2_gen = G2Prepared::from(-verification_key.g2_gen);
    91→
    92→        let coset_gens_pow_n = coset_gens
    93→            .iter()
    94→            .map(|&coset_gen| coset_gen.pow_vartime([n as u64]))
    95→            .collect();
    96→
    97→        let coset_fft_gens = coset_gens.iter().map(|gen| CosetFFT::new(*gen)).collect();
    98→
    99→        Self {
   100→            verification_key,
   101→            coset_gens_bit_reversed: coset_gens,
   102→            coset_domain,
   103→            tau_pow_n,
   104→            neg_g2_gen,
   105→            bit_reversed_coset_gens_pow_n: coset_gens_pow_n,
   106→            bit_reversed_coset_fft_gens: coset_fft_gens,
   107→        }
   108→    }
   109→
   110→    /// Verify multiple multi-opening proofs.
   111→    ///
   112→    /// Panics if the following slices do not have the same length:
   113→    ///
   114→    /// - commitment_indices
   115→    /// - bit_reversed_coset_indices
   116→    /// - bit_reversed_coset_evals
   117→    /// - bit_reversed_proofs
   118→    ///
   119→    /// This corresponds to the guarantee that every opening should have an `input_point` and an `output_point`
   120→    /// with a corresponding proof attesting to `f(input_point) = output_point` and a commitment to the polynomial `f`.
   121→    ///
   122→    /// Note: Although this method is on the `FK20Verifier` structure, it is possible to verify methods that are not
   123→    /// created by the `FK20Prover`. FK20Prover generates multi-proofs efficiently using the FK20 strategy, but we
   124→    /// could just as well generate those proofs using the naive strategy that we test FK20 against. We leave this
   125→    /// naming as is since it conveys a meaningful difference between the other internal provers which do not use FK20.
   126→    /// On the API level, we however export this as Verifier.
   127→    ///
   128→    /// The matching function in the spec is: https://github.com/ethereum/consensus-specs/blob/13ac373a2c284dc66b48ddd2ef0a10537e4e0de6/specs/_features/eip7594/polynomial-commitments-sampling.md#verify_cell_kzg_proof_batch_impl
   129→    pub fn verify_multi_opening(
   130→        &self,
   131→
   132→        deduplicated_commitments: &[G1Point],
   133→        commitment_indices: &[CommitmentIndex],
   134→
   135→        bit_reversed_coset_indices: &[CosetIndex],
   136→        bit_reversed_coset_evals: &[Vec<Scalar>],
   137→        bit_reversed_proofs: &[G1Point],
   138→    ) -> Result<(), VerifierError> {
   139→        assert_eq!(
   140→            commitment_indices.len(),
   141→            bit_reversed_proofs.len(),
   142→            "Expected to have a proof for each commitment opening"
   143→        );
   144→        assert_eq!(
   145→            bit_reversed_coset_indices.len(),
   146→            bit_reversed_proofs.len(),
   147→            "Expected to have a proof for each index we want to open at"
   148→        );
   149→        assert_eq!(
   150→            bit_reversed_coset_evals.len(),
   151→            bit_reversed_proofs.len(),
   152→            "Expected to have a proof for each evaluation we want to prove an opening for"
   153→        );
   154→        let all_same_size = bit_reversed_coset_evals
   155→            .windows(2)
   156→            .all(|w| w[0].len() == w[1].len());
   157→        assert!(
   158→            all_same_size,
   159→            "Expected all cosets to have the same number of elements"
   160→        );
   161→
   162→        // The batch size corresponds to how many openings, we ultimately want to be verifying.
   163→        let batch_size = bit_reversed_coset_indices.len();
   164→
   165→        // 1. Compute random challenges for batching the opening together.
   166→        //
   167→        // From hereon out, `random` will refer to using these random challenges.
   168→        //
   169→        // We compute one challenge `r` using fiat-shamir and the rest are powers of `r`
   170→        // This is safe because of the Schwartz-Zippel Lemma.
   171→        let r = compute_fiat_shamir_challenge(
   172→            &self.verification_key,
   173→            deduplicated_commitments,
   174→            commitment_indices,
   175→            bit_reversed_coset_indices,
   176→            bit_reversed_coset_evals,
   177→            bit_reversed_proofs,
   178→        );
   179→        let r_powers = compute_powers(r, batch_size);
   180→        let num_unique_commitments = deduplicated_commitments.len();
   181→
   182→        // 2. Compute a random linear combination of the proofs
   183→        //
   184→        // Safety: This unwrap can never trigger because `r_powers.len()` is `batch_size`
   185→        // and `bit_reversed_proofs.len()` will equal `batch_size` since we must have a proof for each item in the batch.
   186→        let comm_random_sum_proofs = g1_lincomb(bit_reversed_proofs, &r_powers)
   187→            .expect("number of proofs and number of r_powers should be the same");
   188→
   189→        // 3. Compute a weighted random linear combination of the proofs
   190→        //
   191→        // Where the `weight` refers to the coset_generators to the power of `n`
   192→        let mut weighted_r_powers = Vec::with_capacity(batch_size);
   193→        for (bit_reversed_coset_index, r_power) in bit_reversed_coset_indices.iter().zip(&r_powers)
   194→        {
   195→            let coset_gen_pow_n =
   196→                self.bit_reversed_coset_gens_pow_n[*bit_reversed_coset_index as usize];
   197→            weighted_r_powers.push(r_power * coset_gen_pow_n);
   198→        }
   199→        // Safety: This should never panic since `bit_reversed_proofs.len()` is equal to the batch_size.
   200→        let random_weighted_sum_proofs = g1_lincomb(bit_reversed_proofs, &weighted_r_powers)
