   272→    row_indices: &[u64],
   273→    coset_indices: &[u64],
   274→    coset_evals: &[Vec<Scalar>],
   275→    proofs: &[G1Point],
   276→) -> Scalar {
   277→    const DOMAIN_SEP: &str = "RCKZGCBATCH__V1_";
   278→    let hash_input_size = DOMAIN_SEP.len()
   279→            + size_of::<u64>() // polynomial bound
   280→            + size_of::<u64>() // field elements per coset
   281→            + size_of::<u64>() // num commitments
   282→            + size_of::<u64>() // num cosets
